/**
 * CSS custom-property bridge for the design tokens.
 *
 * `tokens.css` (generated by `scripts/generate-tokens-css.ts` from
 * `renderTokensCss`) defines every color / elevation / motion token as a
 * variable on `:root` / `[data-theme="dark"]` (dark is the default) and on
 * `[data-theme="light"]` / `prefers-color-scheme: light`, and re-binds
 * Tailwind `--color-*` aliases on those same hosts so nested ThemeProviders
 * keep `bg-surface` / `text-text` in sync with `--ui-color-*`. Components
 * compile against `CSS_VAR_COLORS` (`var(--ui-color-*)`), so switching scheme
 * is a single attribute flip on the theme root — no restyle pass through the
 * tree.
 */

import { breakpoint } from './breakpoints';
import { COLOR_PALETTE } from './color-palette';
import type { ColorScheme, ColorTokenName, ColorTokens } from './colors-types';
import { fonts } from './fonts';
import { layer } from './layers';
import { duration, easing } from './motion';
import type { ElevationLevel, ElevationStyle } from './scale';
import {
  borderRadius,
  fontLeading,
  fontSize,
  fontWeight,
  lineHeight,
  makeElevation,
  opacity,
  radiusRole,
  spaceRole,
  spaceSize,
  spacing,
} from './scale';
import { shadowCss } from './shadows';
import { controlSize, iconSize, maxWidth } from './sizes';
import { textStyleCssLines } from './typography';

const COLOR_TOKEN_NAMES = Object.keys(COLOR_PALETTE.light) as ColorTokenName[];

function kebab(name: string): string {
  return name.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase());
}

/** `var(--ui-color-<token>)` for a palette token. */
export function colorVar(name: ColorTokenName): string {
  return `var(--ui-color-${kebab(name)})`;
}

/** Palette-shaped map whose values are CSS variable references. */
export const CSS_VAR_COLORS: ColorTokens = Object.fromEntries(
  COLOR_TOKEN_NAMES.map((name) => [name, colorVar(name)])
) as ColorTokens;

const ELEVATION_LEVELS: readonly ElevationLevel[] = [1, 2, 3, 4, 5];

/**
 * Scheme-agnostic elevation: level N lifts onto `var(--ui-elevation-N)`. Light
 * mode defines the variable as `transparent` (the host's own default), dark
 * mode as the matching surface tier.
 */
export function cssVarElevation(level: ElevationLevel): ElevationStyle {
  if (level === 0) return {};
  return { backgroundColor: `var(--ui-elevation-${level})` };
}

function schemeLines(scheme: ColorScheme): string[] {
  const colors = COLOR_PALETTE[scheme];
  const elevation = makeElevation(colors, scheme);
  const lines: string[] = [];
  for (const name of COLOR_TOKEN_NAMES) {
    lines.push(`  --ui-color-${kebab(name)}: ${colors[name]};`);
  }
  for (const level of ELEVATION_LEVELS) {
    const bg = elevation(level).backgroundColor ?? 'transparent';
    lines.push(`  --ui-elevation-${level}: ${bg};`);
  }
  // Tailwind `@theme` registers `--color-*` as `var(--ui-color-*)` on `:root`.
  // Those aliases compute once on `<html>` — nested ThemeProviders that only
  // flip host `data-theme` would otherwise keep the outer scheme's resolved
  // `--color-*` values. Re-bind every alias on the scheme host so `bg-surface`
  // / `text-text` follow the nearest `[data-theme]`.
  for (const name of COLOR_TOKEN_NAMES) {
    const k = kebab(name);
    lines.push(`  --color-${k}: var(--ui-color-${k});`);
  }
  for (const level of ELEVATION_LEVELS) {
    lines.push(`  --color-elevation-${level}: var(--ui-elevation-${level});`);
  }
  // The shadow names `--ui-color-shadow-color`, so it is bound on the scheme
  // host too: a nested theme recomputes it with its own shadow color.
  for (const [name, value] of Object.entries(shadowCss)) {
    lines.push(`  --ui-shadow-${name}: ${value};`);
  }
  // Default on-color cascade for icons/text outside an OnColorProvider.
  lines.push('  --ui-on-fg: var(--ui-color-text);');
  lines.push('  --ui-on-fg-muted: var(--ui-color-text-secondary);');
  lines.push('  --ui-on-icon: var(--ui-color-icon);');
  lines.push(`  color-scheme: ${scheme};`);
  return lines;
}

/**
 * Dark is the default canvas: `:root` carries it before any script runs.
 * Light applies on `[data-theme="light"]`, and on an unthemed document whose
 * device prefers light. A nested `[data-theme]` host re-binds every role.
 */
function schemeBlocks(): string[] {
  const dark = schemeLines('dark').join('\n');
  const light = schemeLines('light').join('\n');
  const indented = light.replace(/^ {2}/gm, '    ');
  return [
    `:root,\n[data-theme="dark"] {\n${dark}\n}`,
    `[data-theme="light"] {\n${light}\n}`,
    `@media (prefers-color-scheme: light) {\n  :root:not([data-theme]) {\n${indented}\n  }\n}`,
  ];
}

function scaleBlock(): string {
  const lines: string[] = [];
  for (const [key, value] of Object.entries(spacing)) {
    lines.push(`  --ui-space-${key.replace('.', '-')}: ${value}px;`);
  }
  for (const [key, value] of Object.entries(spaceRole)) {
    lines.push(`  --ui-space-${key}: ${value}px;`);
  }
  for (const [key, value] of Object.entries(fonts)) {
    lines.push(`  --ui-font-${key}: ${value};`);
  }
  for (const [key, value] of Object.entries(fontSize)) {
    lines.push(`  --ui-font-size-${key}: ${value}px;`);
  }
  for (const [key, value] of Object.entries(fontLeading)) {
    lines.push(`  --ui-leading-${key}: ${value}px;`);
  }
  for (const [key, value] of Object.entries(lineHeight)) {
    lines.push(`  --ui-line-height-${key}: ${value};`);
  }
  for (const [key, value] of Object.entries(borderRadius)) {
    lines.push(`  --ui-radius-${key}: ${value}px;`);
  }
  for (const [key, value] of Object.entries(duration)) {
    lines.push(`  --ui-duration-${key}: ${value}ms;`);
  }
  for (const [key, value] of Object.entries(easing)) {
    lines.push(`  --ui-easing-${key}: ${value};`);
  }
  lines.push(...semanticScaleLines());
  lines.push(...textStyleCssLines());
  return `:root {\n${lines.join('\n')}\n}`;
}

/** `55%` for the fraction `0.55`, without binary-float noise. */
function percent(fraction: number): string {
  return `${Math.round(fraction * 1000) / 10}%`;
}

/**
 * The scales `token-names.ts` names (`SpaceToken`, `RadiusToken`, …), after
 * the raw scales so every older variable keeps its line.
 */
function semanticScaleLines(): string[] {
  const px = (prefix: string, scale: Readonly<Record<string, number>>) =>
    Object.entries(scale).map(
      ([key, value]) => `  --ui-${prefix}-${key}: ${value}px;`
    );
  // `none`, `sm` and `full` are already the raw steps of the same name.
  const rawRadii = new Set(Object.keys(borderRadius));
  const namedRadii = Object.fromEntries(
    Object.entries(radiusRole).filter(([key]) => !rawRadii.has(key))
  );
  return [
    ...px('space', spaceSize),
    ...px('radius', namedRadii),
    ...Object.entries(fontWeight).map(
      ([key, value]) => `  --ui-font-weight-${key}: ${value};`
    ),
    ...px('icon-size', iconSize),
    ...px('control-size', controlSize),
    ...px('max-width', maxWidth),
    ...px('breakpoint', breakpoint),
    ...Object.entries(layer).map(
      ([key, value]) => `  --ui-layer-${key}: ${value};`
    ),
    ...Object.entries(opacity).map(
      ([key, value]) => `  --ui-opacity-${key}: ${percent(value)};`
    ),
  ];
}

/** Full contents of `tokens.css`. Pure; the generator script writes it. */
export function renderTokensCss(): string {
  return (
    [
      '/* GENERATED from pkgs/ui-root-shared-ts/src/design-tokens.json — do not edit. */',
      scaleBlock(),
      ...schemeBlocks(),
    ].join('\n\n') + '\n'
  );
}
